package com.example.payment.domain.order;

import com.example.payment.domain.shared.Money;
import java.util.Objects;

/** An order placed by a customer; it can be cancelled only while pending. */
public final class Order {

    private final String id;
    private final String customerId;
    private final Money total;
    private OrderStatus status;

    public Order(String id, String customerId, Money total, OrderStatus status) {
        this.id = Objects.requireNonNull(id);
        this.customerId = Objects.requireNonNull(customerId);
        this.total = Objects.requireNonNull(total);
        this.status = Objects.requireNonNull(status);
    }

    public String id() {
        return id;
    }

    public String customerId() {
        return customerId;
    }

    public Money total() {
        return total;
    }

    public synchronized OrderStatus status() {
        return status;
    }

    public boolean belongsTo(String customer) {
        return customerId.equals(customer);
    }

    public synchronized void cancel() {
        if (status != OrderStatus.PENDING) throw new OrderNotCancellableException(id, status);
        status = OrderStatus.CANCELLED;
    }
}
