package com.example.payment.app;

import com.example.payment.application.order.CancelOrder;
import com.example.payment.application.order.GetOrder;
import com.example.payment.application.order.OrderNotFoundException;
import com.example.payment.domain.order.Order;
import com.example.payment.domain.order.OrderNotCancellableException;
import java.math.BigDecimal;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
class OrderController {

    record OrderResponse(String id, String customerId, BigDecimal amount, String currency, String status) {
        static OrderResponse of(Order order) {
            return new OrderResponse(order.id(), order.customerId(), order.total().amount(),
                    order.total().currency(), order.status().name());
        }
    }

    private final GetOrder getOrder;
    private final CancelOrder cancelOrder;

    OrderController(GetOrder getOrder, CancelOrder cancelOrder) {
        this.getOrder = getOrder;
        this.cancelOrder = cancelOrder;
    }

    @GetMapping("/orders/{id}")
    OrderResponse get(@RequestHeader("X-Customer-Id") String customerId, @PathVariable String id) {
        return OrderResponse.of(getOrder.handle(customerId, id));
    }

    @PostMapping("/orders/{id}/cancel")
    OrderResponse cancel(@RequestHeader("X-Customer-Id") String customerId, @PathVariable String id) {
        return OrderResponse.of(cancelOrder.handle(customerId, id));
    }

    // Orders of other customers are reported as not found so their existence is not leaked.
    @ExceptionHandler(OrderNotFoundException.class)
    @ResponseStatus(HttpStatus.NOT_FOUND)
    void notFound() {
    }

    @ExceptionHandler(OrderNotCancellableException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    String notCancellable(OrderNotCancellableException e) {
        return e.getMessage();
    }
}
